# Solution code for the Cypher problem

def get_divisors(n):
    """Get all divisors of n greater than 1."""
    divs = []
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            divs.append(i)
            if i != n // i:
                divs.append(n // i)
    if n > 1:
        divs.append(n)
    return sorted(divs)

def gcd(a, b):
    """Compute GCD of two numbers."""
    while b:
        a, b = b, a % b
    return a

