import sys

def compute_grundy(a, k, memo):
    """Compute Grundy number for a single pile of size a with parameter k."""
    if a in memo:
        return memo[a]

    # Possible moves
    moves = set()

    # Option 1: Remove 1 cow (only if a > 0)
    if a > 0:
        moves.add(compute_grundy(a - 1, k, memo))

    # Option 2: If a is even, replace with k piles of a/2
    if a > 0 and a % 2 == 0:
        x = a // 2
        if k % 2 == 1:
            # If k is odd, XOR sum is grundy(x)
            moves.add(compute_grundy(x, k, memo))
        else:
            # If k is even, XOR sum is 0
            moves.add(0)

    # Compute mex (Minimum Excluded)
    m = 0
    while m in moves:
        m += 1

    memo[a] = m
    return m

