def greedy_stable_matching(n, adj):
    """Greedy approach for finding stable matching."""
    if n % 2 == 1:
        return None

    # Create initial pairing based on minimum costs
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            total_cost = adj[i][j] + adj[j][i]
            edges.append((total_cost, i, j))

    edges.sort()

    pairings = [-1] * n
    used = set()

    for cost, u, v in edges:
        if u not in used and v not in used:
            pairings[u] = v
            pairings[v] = u
            used.add(u)
            used.add(v)

    # Verify stability
    if is_stable(n, pairings, adj):
        return pairings

    return None


