        if len(parts) >= 3:
            u, v, w = parts
            edges.append((u - 1, v - 1, w))  # Convert to 0-indexed

    # Total weight of all edges
    total_edge_weight = sum(w for u, v, w in edges)

    # Build flow network
    # S = 0, T = 2n+m+1
    # Vertices 1..n, Edge nodes n+1..n+m
    S = 0
    T = 2 * n + m + 1
