    # Each edge node connects to both vertices with infinity capacity
    # Each vertex connects to T with capacity = vertex weight

    INF = float('inf')

    for i, (u, v, w) in enumerate(edges):
        edge_node = n + 1 + i
        dinic.add_edge(S, edge_node, w)
