MOD_EXP = MOD - 1

def mat_mul(A, B):
    C = [[0, 0, 0] for _ in range(3)]
    for i in range(3):
        for j in range(3):
            s = 0
            for k in range(3):
                s = (s + A[i][k] * B[k][j]) % MOD_EXP
            C[i][j] = s
    return C

def mat_pow(A, p):
    result = [[1, 0, 0], [0, 1, 0], [0, 0, 1]]
    base = [row[:] for row in A]
    while p > 0:
        if p % 2 == 1:
            result = mat_mul(result, base)
        base = mat_mul(base, base)
        p //= 2
    return result

