    for opt in opts:
        u, v, idx = opt
        edges.append((u, v, idx))

    parent = list(range(2002))
    rank = [0] * 2002

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
        return True

    edges.sort()
    mst_edges = []

    for u, v, idx in edges:
        if union(u, v):
            mst_edges.append(idx)

    return mst_edges

