        return '0\n'

    parts = lines[0].split()
    if len(parts) < 2:
        return '0\n'
    n, m = int(parts[0]), int(parts[1])

    s = lines[1].strip()
    t = lines[2].strip()

    # Validate constraints
    if m < 1 or n < m:
        return '0\n'

    result = []

    # Check each possible starting position
    for i in range(n - m + 1):
        # Build forward mapping (source -> target)
        # Build reverse mapping (target -> source)
        forward = {}
        reverse = {}
        possible = True

        for j in range(m):
            c_in = s[i + j]
            c_out = t[j]

            # Check forward mapping consistency
            if c_in in forward:
                if forward[c_in] != c_out:
                    possible = False
                    break
            else:
                forward[c_in] = c_out

            # Check reverse mapping consistency (no two different sources map to same target)
            if c_out in reverse:
                if reverse[c_out] != c_in:
                    possible = False
                    break
            else:
                reverse[c_out] = c_in

        # Also need to verify the same pairs constraint:
        # A mutual pair means we can designate it as a swap pair
        # For example, if 'a' maps to 'b', we can designate ('a', 'b') as a pair
        # The encoding is symmetric: 'a' -> 'b' and 'b' -> 'a'
        # So we just need a valid bijection

        if possible:
            result.append(i + 1)  # 1-indexed position

    result.sort()

    output = [str(len(result))]
    if result:
        output.append(' '.join(map(str, result)))

    return '\n'.join(output)

