def find_edges_to_remove(n, m, s, t, edges):
    """
    Find the minimum cost to disconnect s and t by removing at most 2 edges.
    Returns (min_cost, num_edges, edge_indices) or (-1, 0, []) if impossible.
    """
    edge_data = []
    for i in range(m):
        if i < len(edges):
            u, v, w = edges[i]
            edge_data.append((u, v, w, i))

    # Case 0: Check if already disconnected
    adj = [[] for _ in range(n + 1)]
    for u, v, _, _ in edge_data:
        adj[u].append((v, len(edge_data) - 1))
        adj[v].append((u, len(edge_data) - 1))

    visited = [False] * (n + 1)
    queue = deque([s])
    visited[s] = True

    while queue:
        u = queue.popleft()
        if u == t:
            return (0, 0, [])
        for v, idx in adj[u]:
            if not visited[v]:
                visited[v] = True
                queue.append(v)

    # Case 1: Try removing 1 edge
    for i in range(m):
        if i < len(edge_data):
            u, v, w, orig_idx = edge_data[i]

            # Build adjacency without this edge
            adj = [[] for _ in range(n + 1)]
            for idx, (x, y, ww, _) in enumerate(edge_data):
                if orig_idx != idx:
                    adj[x].append((y, idx))
                    adj[y].append((x, idx))

            visited = [False] * (n + 1)
            queue = deque([s])
            visited[s] = True

            while queue:
                u = queue.popleft()
                if u == t:
                    break
                for v, idx in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        queue.append(v)

            if t not in visited:
                return (w, 1, [orig_idx + 1])

    # Case 2: Try removing 2 edges
    # To optimize, we consider edges that are on different paths
    # We'll iterate over pairs but limit by finding good candidates

    # First, collect all edges incident to s or t as prime candidates
    incident_edges = set()
    for i, (u, v, w, idx) in enumerate(edge_data):
        if u == s or u == t or v == s or v == t:
            incident_edges.add(idx)

    # Also consider all edges for smaller graphs
    all_idx = set(range(m))

    # Try pairs starting with incident edges as they're most likely to be in the cut
    candidates = list(incident_edges) if len(incident_edges) < m else list(all_idx)

    if not candidates:
        return (-1, 0, [])

    candidates = sorted(set(candidates))

    # For efficiency, only consider edges in paths from s
    adj_full = [[] for _ in range(n + 1)]
    for u, v, w, idx in edge_data:
        adj_full[u].append(v)
        adj_full[v].append(u)

    # Find edges reachable from s
    queue = deque([s])
    reachable = {s}
    while queue:
        u = queue.popleft()
        for v in adj_full[u]:
            if v not in reachable:
                reachable.add(v)
                queue.append(v)

    # Only consider edges in the connected component of s
    candidate_pairs = []
    edge_indices = []

    for i in range(m):
        u, v, w, orig_idx = edge_data[i]
        if reachable and (u in reachable or v in reachable):
            edge_indices.append((orig_idx + 1, w, (u, v)))

    edge_indices.sort(key=lambda x: x[1])

    # Try pairs of edges
    best_cost = float('inf')
    best_pair = None

    num_edges = len(edge_indices)

    # Limit search space for efficiency
    max_attempts = 50000
    attempt_count = 0

    for i in range(min(num_edges, 10000)):
        if attempt_count >= max_attempts:
            break
        attempt_count += 1

        u1, v1, w1, idx1 = edge_indices[i][0], edge_indices[i][1], edge_indices[i][2], edge_indices[i][3]

        # Remove first edge
        adj = [[] for _ in range(n + 1)]
        for ux, vx, ww, idx in edge_data:
            if (idx != i):
                adj[ux].append(vx)
                adj[vx].append(ux)

        # Get reachable from s after removing first edge
        queue = deque([s])
        reach1 = {s}
        visited = [False] * (n + 1)
        visited[s] = True
        while queue:
            curr = queue.popleft()
            if curr == t:
                continue
            for nxt in adj[curr]:
                if not visited[nxt]:
                    visited[nxt] = True
                    reach1.add(nxt)
                    queue.append(nxt)

        # If t is reachable, we need to find an edge that blocks the path from reach1
        if t not in visited:
            # t is not reachable even after removing first edge
            if w1 + w1 < best_cost:  # Need to consider both edges
                continue

        # To be more efficient, only try second edge that could block paths to t
        # from clients of first removal

        if t in visited:
            # t is reachable, we need to block paths further
            for j in range(i + 1, min(num_edges, i + 5000)):
                u2, v2, w2, idx2 = edge_indices[j][0], edge_indices[j][1], edge_indices[j][2], edge_indices[j][3]

                # Remove both edges
                adj2 = [[] for _ in range(n + 1)]
                for ux, vx, ww, idx in edge_data:
                    if idx != i and idx != j:
                        adj2[ux].append(vx)
                        adj2[vx].append(ux)

                visited = [False] * (n + 1)
                queue = deque([s])
                visited[s] = True

                while queue:
                    curr = queue.popleft()
                    if curr == t:
                        break
                    for nxt in adj2[curr]:
                        if not visited[nxt]:
                            visited[nxt] = True
                            queue.append(nxt)

                if t not in visited and attempt_count < max_attempts:
                    if w1 + w2 < best_cost:
                        best_cost = w1 + w2
                        best_pair = (idx1, idx2)
                        break  # lower cost found
                        attempt_count += 1

    if best_pair is not None and best_cost < float('inf'):
        return (best_cost, 2, [best_pair[0], best_pair[1]])

    return (-1, 0, [])

