def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    n, m = map(int, lines[0].split())

    graph = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        if i < len(lines):
            u, v = map(int, lines[i].split())
            graph[u].append(v)

    # BFS from each node to compute shortest distances to all other nodes
    # dist[i][j] = shortest distance from i to j
    dist = [[float('inf')] * (n + 1) for _ in range(n + 1)]

    for start in range(1, n + 1):
        dist[start][start] = 0
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in graph[u]:
                if dist[start][v] == float('inf'):
                    dist[start][v] = dist[start][u] + 1
                    queue.append(v)

    # Find the best 4 distinct cities (a, b, c, d) maximizing d(a,b) + d(b,c) + d(c,d)
    max_dist = -1
    best_quad = (1, 2, 3, 4)

    # Iterate through all pairs of middle cities (b, c)
    for b in range(1, n + 1):
        for c in range(1, n + 1):
            if b == c:
                continue

            d_bc = dist[b][c]
            if d_bc == float('inf'):
                continue

            # Find best a (maximize d(a, b)) where a != b and a != c
            best_a = -1
            best_da_b = -1

            for a in range(1, n + 1):
                if a == b or a == c:
                    continue
                da_b = dist[a][b]
                if da_b < float('inf') and da_b > best_da_b:
                    best_da_b = da_b
                    best_a = a

            # Find best d (maximize d(c, d)) where d != b and d != c
            best_d = -1
            best_dc = -1

            for d in range(1, n + 1):
                if d == b or d == c:
                    continue
                dc = dist[c][d]
                if dc < float('inf') and dc > best_dc:
                    best_dc = dc
                    best_d = d

            # Check if we found valid a and d
            if best_a != -1 and best_d != -1:
                # Check that all 4 are distinct (a, b, c, d should all be different)
                if len({best_a, b, c, best_d}) != 4:
                    continue

                total = dist[best_a][b] + d_bc + dist[c][best_d]
                if total > max_dist:
                    max_dist = total
                    best_quad = (best_a, b, c, best_d)

    return " ".join(map(str, best_quad))


