import math

def solution(input_text):
    """
    Solution to find the minimum non-negative time when all mice are strictly 
    inside the mousetrap rectangle.
    """
    lines = input_text.strip().split('\n')
    n = int(lines[0])
    x1, y1, x2, y2 = map(int, lines[1].split())

    # Initialize the overall valid time interval
    result_start = float('-inf')
    result_end = float('inf')

    for i in range(2, 2 + n):
        rix, riy, vix, viy = map(int, lines[i].split())

        # Calculate valid interval for x dimension
        x_start, x_end = float('-inf'), float('inf')
        if vix == 0:
            if x1 < rix < x2:
                x_start, x_end = 0.0, float('inf')
            else:
                return "-1"
        elif vix > 0:
            t1 = (x1 - rix) / float(vix)
            t2 = (x2 - rix) / float(vix)
            if t1 < t2:
                x_start, x_end = t1, t2
            else:
                return "-1"
        else:  # vix < 0
            t1 = (x2 - rix) / float(vix)
            t2 = (x1 - rix) / float(vix)
            if t1 < t2:
                x_start, x_end = t1, t2
            else:
                return "-1"

        # Calculate valid interval for y dimension
        y_start, y_end = float('-inf'), float('inf')
        if viy == 0:
            if y1 < riy < y2:
                y_start, y_end = 0.0, float('inf')
            else:
                return "-1"
        elif viy > 0:
            t1 = (y1 - riy) / float(viy)
            t2 = (y2 - riy) / float(viy)
            if t1 < t2:
                y_start, y_end = t1, t2
            else:
                return "-1"
        else:  # viy < 0
            t1 = (y2 - riy) / float(viy)
            t2 = (y1 - riy) / float(viy)
            if t1 < t2:
                y_start, y_end = t1, t2
            else:
                return "-1"

        # Find intersection of intervals
        result_start = max(result_start, x_start, y_start)
        result_end = min(result_end, x_end, y_end)

        if result_start >= result_end:
            return "-1"

    # Clamp result_start to be non-negative
    result_start = max(result_start, 0.0)

    # If the interval is valid, return the start (minimum time)
    if result_start < result_end:
        return str(result_start)

    return "-1"

