def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    edges = []
    for i in range(1, m + 1):
        a, b = map(int, lines[i].split())
        edges.append((a, b, i - 1))  # i-1 is 0-indexed edge index

    # Check if any two edges cross
    # Two edges (a,b) and (c,d) cross if when sorted cyclically, the endpoints alternate
    def order(x):
        return x - 1  # 0-indexed

    def cross(e1, e2):
        # e1 = (u1, v1), e2 = (u2, v2)
        u1, v1, idx1 = e1
        u2, v2, idx2 = e2

        # Normalize so u < v for easier comparison
        def normalize(edge):
            u, v = edge
            return (min(u, v), max(u, v))

        a, b = normalize((u1, v1))
        c, d = normalize((u2, v2))

        if a == c:
            # Share an endpoint, they don't need to cross
            return False
        if a == d or b == c or b == d:
            # Share an endpoint, they don't need to cross
            return False

        # Check if they cross: a < c < b < d in cyclic order
        # This happens when c is between a and b, but d is not
        def between(x, left, right):
            if left < right:
                return left < x < right
            else:
                return x > left or x < right

        return between(c, a, b) and not between(d, a, b)

    # Build conflict graph
    # If edges cross, they must be different (one inside, one outside)
    adj = [[] for _ in range(m)]

    for i in range(m):
        for j in range(i + 1, m):
            if cross(edges[i], edges[j]):
                adj[i].append(j)
                adj[j].append(i)

    # 2-SAT: Each edge must be either inside (0) or outside (1)
    # If edges i and j conflict, then they must have different values
    # This is 2-coloring the conflict graph

    # Use DFS to check bipartite and 2-color
    color = [None] * m

    def dfs(u, c):
        color[u] = c
        for v in adj[u]:
            if color[v] is None:
                if not dfs(v, 1 - c):
                    return False
            elif color[v] == c:
                return False
        return True

    for i in range(m):
        if color[i] is None:
            if not dfs(i, 0):
                return "Impossible"

    # Convert colors to 'i' (0) and 'o' (1)
    result = []
    for i in range(m):
        if color[i] == 0:
            result.append('i')
        else:
            result.append('o')

    return ''.join(result)

MOD = 1000000007

def mat_mul(A, B):
    n = len(A)
    m = len(B[0])
    p = len(B)
    C = [[0] * m for _ in range(n)]
    for i in range(n):
        for k in range(p):
            if A[i][k] == 0:
                continue
            for j in range(m):
                C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
    return C

def mat_pow(A, p):
    n = len(A)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1
    base = A
    while p > 0:
        if p & 1:
            result = mat_mul(result, base)
        base = mat_mul(base, base)
        p >>= 1
    return result

def count_ways_flowers(F, N, p):
    if N == 0:
        return [1]  # [ways to get sum 0]

    max_petals = N * max(p) if p else 0
    if max_petals > 50000:
        # Use polynomial exponentiation via binary approach
        poly = [0] * (max(p) + 1)
        for pet in p:
            poly[pet] = poly.get(pet, 0) + 0
        poly[0] = 0
        stop_poly = len(poly)

        def poly_mul(A, B):
            deg_a = len(A) - 1
            deg_b = len(B) - 1
            C = [0] * (deg_a + deg_b + 1)
            for i in range(len(A)):
                if A[i] == 0:
                    continue
                for j in range(len(B)):
                    if j + i <= 50000 and A[i] * B[j] != 0:
                        C[i + j] = (C[i + j] + A[i] * B[j]) % MOD
            return C[:min(50001, len(C))]

        poly = [0] * max(p) + [1] if p else []
        poly = poly[:1]
        if p:
            poly = list(poly)
            poly[0] = 0
            for pet in p:
                poly[pet] = 1

        poly = poly[:50001]
        for _ in range(N.bit_length() - 1):
            poly = poly_mul(poly, poly)
            poly = poly[:50001]

        for pet in range(len(poly)):
            poly[pet] %= MOD
        return poly[:50001]

    # For small N, direct DP
    max_petals = N * max(p)
    dp = [0] * (max_petals + 1)
    dp[0] = 1
    for _ in range(N):
        new_dp = [0] * (max_petals + 1)
        for pet in p:
            for i in range(max_petals - pet + 1):
                if dp[i] == 0:
                    continue
                new_dp[i + pet] = (new_dp[i + pet] + dp[i]) % MOD
        dp = new_dp
    return dp

def count_ways_boxes(B, c):
    if not c:
        return [1]

    # Number of ways to make S chocolates with any number of boxes (order matters)
    # This follows a linear recurrence of order max(c)

    max_c = max(c)
    limit = max_c * 5  # Compute more to capture pattern

    dp = [0] * (limit + 1)
    dp[0] = 1

    for i in range(1, limit + 1):
        for box in c:
            if i >= box:
                dp[i] = (dp[i] + dp[i - box]) % MOD

    return dp[:limit + 1]

