import itertools

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    if n == 0:
        return '0'

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for i in range(1, len(lines)):
        parts = lines[i].split()
        if len(parts) >= 2:
            u, v = int(parts[0]), int(parts[1])
            adj[u].append(v)
            adj[v].append(u)

    # Find connected components
    visited_all = [False] * n
    components = []
    for i in range(n):
        if not visited_all[i]:
            component = []
            stack = [i]
            visited_all[i] = True
            while stack:
                node = stack.pop()
                component.append(node)
                for neighbor in adj[node]:
                    if not visited_all[neighbor]:
                        visited_all[neighbor] = True
                        stack.append(neighbor)
            components.append(component)

    def get_inactive_reachable(node, active, n, adj):
        """Find all inactive nodes reachable from node through inactive nodes only, including node itself"""
        reachable = set()
        reachable.add(node)
        stack = [node]
        while stack:
            curr = stack.pop()
            for nbr in adj[curr]:
                if nbr not in active and nbr not in reachable:
                    reachable.add(nbr)
                    stack.append(nbr)
        return reachable

    def calc_score(order, n, adj):
        """Calculate total potential for a given activation order"""
        active = set()
        total = 0
        for node in order:
            # Find inactive nodes reachable from this node (before activating it)
            inactive_reachable = get_inactive_reachable(node, active, n, adj)
            total += len(inactive_reachable)
            active.add(node)
        return total

    def solve_comp(comp, n, adj):
        """Find maximum potential for a component"""
        if len(comp) <= 10:
            # Try all permutations for small components
            max_score = 0
            for perm in itertools.permutations(comp):
                score = calc_score(perm, n, adj)
                max_score = max(max_score, score)
            return max_score
        else:
            # For larger components, use heuristic based on degree
            comp_degree = sorted(comp, key=lambda x: len(adj[x]), reverse=True)
            return calc_score(comp_degree, n, adj)

    # Sum up potentials for all components
    result = sum(solve_comp(comp, n, adj) for comp in components)
    return str(result)

