def solution(input_data: str) -> str:
    lines = input_data.strip().split('\n')
    ts, tf, t = map(int, lines[0].split())
    n = int(lines[1])
    arrivals = list(map(int, lines[2].split())) if n > 0 else []

    if n == 0:
        return str(ts) + '\n'

    finish_times = []
    current_finish = ts

    for arrival in arrivals:
        if arrival < current_finish:
            current_finish += t
        else:
            current_finish = max(arrival, current_finish) + t
        finish_times.append(current_finish)

    valid_departures = [f for f in finish_times if f <= tf]

    if valid_departures:
        return str(min(valid_departures)) + '\n'
    else:
        return str(ts) + '\n'

