    # Count numbers in [1, N] with each residue mod 9
    # cnt[r] = count of x where x % 9 = r
    cnt = [0] * 9
    for r in range(9):
        if r == 0:
            cnt[r] = (N + 8) // 9
        else:
            cnt[r] = (N - r) // 9 + 1

    # Count all triples where A*B % 9 == C % 9
    matches = 0
    for a in range(9):
        for b in range(9):
            res = (a * b) % 9
            # cnt[a] * cnt[b] gives number of pairs (A,B) with residues (a,b)
            # cnt[res] gives number of C with residue res
            matches += cnt[a] * cnt[b] * cnt[res]

    # Count triples where A*B = C exactly
    exact = 0
    for A in range(1, N + 1):
        exact += N // A

    return matches - exact

