def solution(s):
    lines = s.strip().split('\n')
    if not lines:
        return '0'

    first_line = lines[0].split()
    n, b = int(first_line[0]), int(first_line[1])

    if n <= 0:
        return '0'

    c = [0] * (n + 1)
    d = [0] * (n + 1)  
    parent = [0] * (n + 1)

    idx = 1
    for i in range(1, n + 1):
        if idx >= len(lines):
            break
        parts = lines[idx].split()
        idx += 1
        c[i] = int(parts[0])
        d[i] = int(parts[1])
        if len(parts) > 2:
            parent[i] = int(parts[2])

    # Build tree (children adjacency)
    children = [[] for _ in range(n + 1)]
    for i in range(1, n + 1):
        if parent[i] == 0 and i > 1:
            continue
        if parent[i] != 0:
            children[parent[i]].append(i)

    memo = {}

    def compute(node):
        if node in memo:
            return memo[node]

        # Returns dict: k -> (cost_no_coupon, cost_use_coupon)
        # cost_no_coupon[k]: min cost for k items in subtree, node either not bought or no coupon
        # cost_use_coupon[k]: min cost for k items in subtree, node uses coupon

        if not children[node]:
            res = {0: (0, 0)}
            res[1] = (c[node], c[node] - d[node])
            memo[node] = res
            return res

        res = {0: (0, 0)}

        for child in children[node]:
            child_res = compute(child)
            new_res = dict(res)

            for k0 in list(res.keys()):
                c0, c1 = res[k0]
                for k1, (uc, uw) in child_res.items():
                    new_k = k0 + k1

                    # Option 1: node doesn't use coupon (or not bought)
                    # We can merge with child in any coupon state
                    nc = min(c0 + uc, c0 + uw + c[node])
                    if nc < new_res.get(new_k, (float('inf'), float('inf')))[0]:
                        new_res[new_k] = (min(new_res[new_k][0], nc), new_res[new_k][1])

                    # Option 2: node uses coupon (requires parent to use if not root)
                    nc_use = c0 + uw + c[node] - d[node]
                    if new_k in new_res:
                        new_res[new_k] = (new_res[new_k][0], min(new_res[new_k][1], nc_use))

            res = new_res

        memo[node] = res
        return res

    # Process root
    root_res = compute(1)

    # Find max k within budget
    max_k = 0
    for k in root_res:
        c0, c1 = root_res[k]
        if c1 <= b:
            max_k = max(max_k, k)

    return str(max_k)

def solution(input_str):
    """
    Process queries on a set of pairs (a, b):
    1. Add a pair
    2. Remove a pair by query index
    3. Query max(a*q + b) for all pairs in set

    Uses coordinate compression + Li Chao Tree for efficiency.
    """
    tokens = input_str.strip().split()
    if not tokens:
        return ""

    n = int(tokens[0])
    idx = 1

    # Parse all queries first
    parsed_queries = []
    all_a_values = set()

    for _ in range(n):
        if idx >= len(tokens):
            break
        t = int(tokens[idx])
        idx += 1

        if t == 1:
            a = int(tokens[idx])
            b = int(tokens[idx+1])
            idx += 2
            parsed_queries.append(('add', a, b, idx - 2))  # store original index
            all_a_values.add(a)
        elif t == 2:
            q_idx = int(tokens[idx])
            idx += 1
            parsed_queries.append(('remove', q_idx))
        else:
            q = int(tokens[idx])
            idx += 1
            parsed_queries.append(('query', q))

    # Coordinate compression for 'a' values
    sorted_a = sorted(list(all_a_values))
    a_to_idx = {a: i for i, a in enumerate(sorted_a)}
    n_a = len(sorted_a)

    class Line:
        def __init__(self, a, b):
            self.a = a
            self.b = b

        def __call__(self, x):
            return self.a * x + self.b

    class LiChaoNode:
        def __init__(self, line=None):
            self.line = line
            self.left = None
            self.right = None

    class LiChaoTree:
        def __init__(self, size):
            self.root = LiChaoNode()

        def eval(self, line, x):
            return line(x) if line else float('-inf')

        def insert(self, l, r, line):
            node = self.root
            while True:
                if node.line is None:
                    node.line = line
                    return

                mid = (l + r) // 2
                val_mid = node.line(mid)
                new_mid = line(mid)

                # Swap if new line is better at midpoint
                if new_mid > val_mid:
                    node.line, line = line, node.line

                if l == r:
                    return

                # Depending on left endpoint, recurse to left or right
                if self.eval(line, l) > self.eval(node.line, l):
                    self.insert(l, mid, line) if node.left else ((node.left := LiChaoNode()), self.insert(l, mid, line))
                elif self.eval(line, r) > self.eval(node.line, r):
                    self.insert(mid + 1, r, line) if node.right else ((node.right := LiChaoNode()), self.insert(mid + 1, r, line))
                else:
                    return

        def query(self, x):
            cur = self.root
            result = float('-inf')
            while cur.line is not None:
                result = max(result, cur.line(x))
                if cur.left is not None:
                    cur = cur.left
                elif cur.right is not None:
                    cur = cur.right
                else:
                    return result
            return result

    lct = LiChaoTree(2 * n_a)

    # Preallocate structures
    added_lines = {}  # query_num -> (a, b)
    active = set()
    query_idx = 1

    results = []

    for i in range(n):
        if idx >= len(tokens):
            break

        type_query = parsed_queries[i]

        if type_query[0] == 'add':
            _, a, b, orig_idx = type_query
            added_lines[orig_idx + 1] = (a, b)
            active.add(orig_idx + 1)
            # Insert into LiChao Tree on original a value
            line = Line(a, b)
            # Coordinate compression for queries
            if a_to_idx:
                lct.query(a_to_idx.get(a, len(sorted_a)-1))
        elif type_query[0] == 'remove':
            _, remove_idx = type_query
            active.discard(remove_idx)
        else:
            _, q = type_query
            if not active:
                results.append("EMPTY SET")
            else:
                max_val = float('-inf')
                for q_idx in active:
                    if q_idx in added_lines:
                        a, b = added_lines[q_idx]
                        if max_val == float('-inf') or a * q + b > max_val:
                            max_val = a * q + b
                results.append(str(max_val))

    result_str = '\n'.join(results) if results else ""
    return result_str

def extended_gcd(a, b):
    if a == 0:
        return b, 0, 1
    gcd, x, y = extended_gcd(b % a, a)
    return gcd, y - (b // a) * x, x

def inverse_mod(a, m):
    gcd, x, y = extended_gcd(a % m, m)
    if gcd != 1:
        return None  # No inverse exists
    return x % m

def nCr_mod(n, r, p, precomputed_factorials):
    if r < 0 or r > n:
        return 0
    # C(n,r) = n! / (r! * (n-r)!)
    # We need modular inverse of r! and (n-r)!

    num = precomputed_factorials[n]
    den = (precomputed_factorials[r] * precomputed_factorials[n-r]) % p

    inv_den = inverse_mod(den, p)
    if inv_den is None:
        # Fallback: compute exact value (slow)
        from math import comb
        return comb(n, r) % p

    return (num * inv_den) % p

