    if len(first_line) >= 4:
        swapLR = int(first_line[2])
        swapUD = int(first_line[3])
    idx += 1

    # Read the grid
    grid = lines[idx:idx+n]
    idx += n

    # Find finish position and parse grid (0-indexed internally)
    finish_pos = None
    dangerous = set()
    for r in range(n):
        for c in range(m):
            if grid[r][c] == 'F':
                finish_pos = (r, c)
            if grid[r][c] == '*':
                dangerous.add((r, c))

    start_pos = (0, 0)

    if finish_pos is None:
        return ""

    # BFS to find shortest path
    q = deque([(start_pos, [])])
    visited = {start_pos}
    path = None

    while q:
        (r, c), p = q.popleft()
        if (r, c) == finish_pos:
            path = p
            break

        # Try all four directions
        for move_char, dr, dc in [('R', 0, 1), ('U', -1, 0), ('L', 0, -1), ('D', 1, 0)]:
            nr, nc = r + dr, c + dc

            # Apply swap logic for direction name (but not for position calculation)
            if swapLR and move_char in ('L', 'R'):
                move_char = 'R' if move_char == 'L' else 'L'
            if swapUD and move_char in ('U', 'D'):
                move_char = 'D' if move_char == 'U' else 'U'

            # Check bounds and if cell is dangerous
            if 0 <= nr < n and 0 <= nc < m and (nr, nc) not in visited and (nr, nc) not in dangerous:
                visited.add((nr, nc))
                q.append(((nr, nc), p + [move_char]))

    if path is None:
        return ""

    # Convert path to output with swap transformations applied
    result = []
    for move in path:
        if swapLR:
            result.append('R' if move == 'L' else 'L')
        elif swapUD:
            result.append('D' if move == 'U' else 'U')
        else:
            result.append(move)

    return '\n'.join(result) + '\n'

