def compute_S_sum(X_str):
    """Compute sum of S(n) for n from 1 to X"""
    MOD = 10**9 + 7
    X_str = X_str.strip()

    if not X_str:
        return "0"

    length = len(X_str)

    if length <= 18:
        X = int(X_str)
        total = 0
        for n in range(1, X + 1):
            sorted_digits = ''.join(sorted(str(n)))
            total = (total + int(sorted_digits)) % MOD
        return str(total)

    # For larger X, use digit DP
    digits = [int(d) for d in X_str]

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, tight):
        if pos == len(digits):
            return 1, 0

        limit = digits[pos] if tight else 9
        total_count = 0
        total_sum = 0

        for d in range(limit + 1):
            count, sum_val = dp(pos + 1, tight and d == limit)
            total_count = (total_count + count) % MOD
            total_sum = (total_sum + sum_val + d * count) % MOD

        return total_count, total_sum

    _, ans = dp(0, True)
    return str(ans % MOD)


