def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].split()))

    # Stack to store (sum, count) for each group being processed
    stack = []

    for x in a:
        # Keep merging with previous group if current element is less than
        # the previous group's average (use integer arithmetic for precision)
        while stack and stack[-1][0] * (stack[-1][1] + 1) > (stack[-1][0] + x) * stack[-1][1]:
            s, c = stack.pop()
            stack.append((s + x, c + 1))
        else:
            stack.append((x, 1))

    # Process stack in reverse order (bottom to top of original processing)
    result = []
    for s, c in reversed(stack):
        val = s / c
        result.extend([val] * c)

    # Format numbers appropriately (integers without decimal, floats at sufficient precision)
    output = []
    for val in result:
        if val == int(val):
            output.append(str(int(val)))
        else:
            output.append(f"{val:.10f}")

    return '\n'.join(output)

def solution(input_str):
    import sys
    sys.setrecursionlimit(500000)
    import math

    lines = input_str.strip().split('\n')

    n, m = map(int, lines[0].split())

    # Build adjacency list (treat as undirected for cycle finding)
    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        a, b, l = map(int, lines[i].split())
        adj[a].append((b, l))
        adj[b].append((a, l))

    q = int(lines[m + 1])

    queries = []
    for i in range(m + 2, m + 2 + q):
        v, s, t = map(int, lines[i].split())
        queries.append((v, s, t))

    visited = [False] * (n + 1)
    dist = {}
    comp = [0] * (n + 1)
    comp_gcd = {}

    def dfs(u, p, d, c):
        visited[u] = True
        dist[u] = d
        comp[u] = c

        for v, w in adj[u]:
            if v == p:
                continue
            if visited[v]:
                # Back edge detected - forms a cycle
                cycle_w = abs(dist[u] - dist[v] - w)
                if cycle_w > 0:
                    if c in comp_gcd:
                        comp_gcd[c] = math.gcd(comp_gcd[c], cycle_w)
                    else:
                        comp_gcd[c] = cycle_w
            else:
                dfs(v, u, d + w, c)

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i, -1, 0, i)

    results = []
    for v, s, t in queries:
        c = comp[v]
        g = comp_gcd.get(c, 0)

        if g == 0:
            # No cycles in this component, only possible if s=0
            # or can reach t (odometer wraps naturally)
            if s % t == 0:
                results.append("YES")
            else:
                results.append("NO")
        else:
            # Need d ≡ (t - s) mod t where d is a multiple of g
            target = (t - s) % t
            if target % g == 0:
                results.append("YES")
            else:
                results.append("NO")

    return '\n'.join(results)

