def solution(input_str):
    a, h, w = map(int, input_str.strip().split())

    if a > h or a > w:
        return "-1\n"

    if a == h and a == w:
        return "0.0000000000\n"

    ans = float('inf')

    n_max = h // a

    for n in range(1, n_max + 1):
        x = (h - n * a) / (n + 1)
        if x < 0:
            continue

        m_max = (w - x) / (a + x)
        if m_max >= 1:
            ans = min(ans, x)

    if ans == float('inf'):
        return "-1\n"

    return f"{ans:.10f}\n"
